    19	type HoldReasonPageProps =
    20	    | PlatformStackScreenProps<MoneyRequestNavigatorParamList, typeof SCREENS.MONEY_REQUEST.HOLD>
    21	    | PlatformStackScreenProps<SearchReportParamList, typeof SCREENS.SEARCH.TRANSACTION_HOLD_REASON_RHP>;
    22	
    23	function HoldReasonPage({route}: HoldReasonPageProps) {
    24	    const {translate} = useLocalize();
    25	
    26	    const {transactionID, reportID, backTo, searchHash} = route.params;
    27	
    28	    const [report] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${reportID || -1}`);
    29	
    30	    // We first check if the report is part of a policy - if not, then it's a personal request (1:1 request)
    31	    // For personal requests, we need to allow both users to put the request on hold
    32	    const isWorkspaceRequest = ReportUtils.isReportInGroupPolicy(report);
    33	    const parentReportAction = ReportActionsUtils.getReportAction(report?.parentReportID ?? '-1', report?.parentReportActionID ?? '-1');
    34	
    35	    const onSubmit = (values: FormOnyxValues<typeof ONYXKEYS.FORMS.MONEY_REQUEST_HOLD_FORM>) => {
    36	        // We have extra isWorkspaceRequest condition since, for 1:1 requests, canEditMoneyRequest will rightly return false
    37	        // as we do not allow requestee to edit fields like description and amount.
    38	        // But, we still want the requestee to be able to put the request on hold
    39	        if (ReportActionsUtils.isMoneyRequestAction(parentReportAction) && !ReportUtils.canEditMoneyRequest(parentReportAction) && isWorkspaceRequest) {
    40	            return;
    41	        }
    42	
    43	        IOU.putOnHold(transactionID, values.comment, reportID, searchHash);
    44	        Navigation.goBack(backTo);
    45	    };
    46	
    47	    const validate = useCallback(
    48	        (values: FormOnyxValues<typeof ONYXKEYS.FORMS.MONEY_REQUEST_HOLD_FORM>) => {
    49	            const errors: FormInputErrors<typeof ONYXKEYS.FORMS.MONEY_REQUEST_HOLD_FORM> = ValidationUtils.getFieldRequiredErrors(values, [INPUT_IDS.COMMENT]);
    50	
    51	            if (!values.comment) {
    52	                errors.comment = translate('common.error.fieldRequired');
    53	            }
    54	            // We have extra isWorkspaceRequest condition since, for 1:1 requests, canEditMoneyRequest will rightly return false
    55	            // as we do not allow requestee to edit fields like description and amount.
    56	            // But, we still want the requestee to be able to put the request on hold
    57	            if (ReportActionsUtils.isMoneyRequestAction(parentReportAction) && !ReportUtils.canEditMoneyRequest(parentReportAction) && isWorkspaceRequest) {
    58	                const formErrors = {};
    59	                ErrorUtils.addErrorMessage(formErrors, 'reportModified', translate('common.error.requestModified'));
    60	                FormActions.setErrors(ONYXKEYS.FORMS.MONEY_REQUEST_HOLD_FORM, formErrors);
    61	            }
    62	
    63	            return errors;
    64	        },
    65	        [parentReportAction, isWorkspaceRequest, translate],
    66	    );
    67	
    68	    useEffect(() => {
    69	        FormActions.clearErrors(ONYXKEYS.FORMS.MONEY_REQUEST_HOLD_FORM);
    70	        FormActions.clearErrorFields(ONYXKEYS.FORMS.MONEY_REQUEST_HOLD_FORM);
    71	    }, []);
    72	
    73	    return (
    74	        <HoldReasonFormView
    75	            onSubmit={onSubmit}
    76	            validate={validate}
    77	            backTo={backTo}
    78	        />
    79	    );
    80	}
    81	
    82	HoldReasonPage.displayName = 'MoneyRequestHoldReasonPage';
    83	
    84	export default HoldReasonPage;
